import {esc} from './models.js?v=0.17.2';
import {preparationHash} from './preparation.js';
export function preparationHTML({path,courses,visits,done,save}){
 const future=path.kind==='specialization',available=courses.get(path.id),resume=visits[path.id],count=path.steps.filter(s=>done.has(s.key)).length;
 const title=key=>{const [c,l]=key.split('/');return courses.get(c).lessons.find(item=>item.id===l).title;};
 return `<div class="breadcrumb"><a href="#map/${path.track}">Learning path</a><span aria-hidden="true">/</span><span>Preparation</span></div><span class="pill">${future?(available?'Advanced course · preparation available':'Future course · preparation available'):'Course preparation'}</span><h1>Prepare for ${esc(path.title)}</h1><p class="map-intro">${esc(path.why)}</p><section class="preparation-start"><h2>One idea at a time</h2><p>${path.steps.length} selected lessons. Each opens with one short idea and one example. Try its changed case before moving on.</p><a class="primary" href="${esc(resume??preparationHash(path.id,path.steps[0].key))}">${resume?'Resume preparation':'Start preparation'} →</a>${resume?`<a href="${preparationHash(path.id,path.steps[0].key)}">Start from the first idea</a>`:''}<p class="subtle">${count} of ${path.steps.length} marked complete. Marks are your own reminders, not a test result. ${save?'Your place is saved in this browser.':'Your place lasts for this page session. Use Progress settings to keep it after closing.'}</p></section><p>${path.id==='foundations'?'Use these lessons whenever a number rule feels unfamiliar. You can repeat them at any time.':'This is a starting path. If the ideas are new, work through the earlier courses and their practice too.'}</p>${path.id!=='foundations'&&path.id!=='math'?'<p><a href="#prepare/math">Need the number basics? Start here.</a></p>':''}<details class="preparation-list"><summary>See the ${path.steps.length} preparation ideas</summary><ol>${path.steps.map(s=>`<li><a href="${preparationHash(path.id,s.key)}">${esc(title(s.key))}</a>${done.has(s.key)?' <span class="subtle">— marked complete</span>':''}<p>${esc(s.why)}</p></li>`).join('')}</ol></details>${path.requiredCourses.length?`<details class="preparation-list"><summary>Earlier courses to work through</summary><ul>${path.requiredCourses.map(id=>`<li><a href="#course/${id}">${esc(courses.get(id).title)}</a> · <a href="#prepare/${id}">Preparation</a></li>`).join('')}</ul><p>Each course has its own preparation links. Open those if an earlier tool is unfamiliar.</p></details>`:''}${future?`<section class="plan-banner">${available?`<h2>${available.status==='complete'?'The defined course is ready':available.modules.length>1?'More course modules are ready':'The first module is ready'}</h2><p>${available.lessons.length} lessons in ${available.modules.length} module${available.modules.length===1?'':'s'} are available. ${available.status==='complete'?'All modules in the defined course are ready; see course coverage for its limits.':'The full advanced course is still in development.'}</p><p><a class="primary" href="#learn/${path.id}/${available.lessons[0].id}/understand">Start the advanced lessons →</a></p><p><a href="#course/${path.id}">${available.status==='complete'?'See course coverage and limits':'See what is ready and what comes later'}</a></p>`:'<h2>The advanced course is still planned</h2><p>You can study the preparation above now. The new course lessons below have not been written yet.</p>'}<details><summary>Tools still needed beyond these refreshers</summary><ul>${path.remainingTools.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details><details><summary>${available?.status==='complete'?'Course direction':'Full course direction · still in development'}</summary><ol>${path.nextTopics.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p>${available?.status==='complete'?'Each topic is split into small lessons':'Each topic needs several small lessons'} with one idea, one example, a labeled equation when useful, and a changed case to try. ${available?.status==='complete'?'The modules now cover this defined direction. Course coverage also lists the limits and further study.':'The available modules cover part of this direction. Course coverage lists the next topics still to come.'}</p></details><details><summary>Scope references</summary><p>These links help check the subject boundaries. This app's selection is independently planned and is not equivalent to those courses.</p><ul>${path.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a></li>`).join('')}</ul></details></section>`:`<p class="preparation-exit"><a href="#course/${path.id}">Open ${esc(path.title)} course coverage →</a></p>`}`;
}
export function preparationContextHTML(path,key){
 const index=path.steps.findIndex(s=>s.key===key);
 return `<aside class="preparation-context" aria-label="Preparation progress"><a href="#prepare/${path.id}">Preparation for ${esc(path.title)}</a><span>Idea ${index+1} of ${path.steps.length}</span><p>${esc(path.steps[index].why)}</p></aside>`;
}
export function specializationLinksHTML(paths,track,courses=new Map()){
 return `<section class="plan-banner"><h2>Advanced courses and preparation</h2><p>Start with the preparation for each subject. Course coverage shows which lessons are ready and which topics remain to be taught.</p><ul>${Object.values(paths).filter(p=>p.kind==='specialization'&&p.track===track).map(p=>`<li><a href="#prepare/${p.id}">${esc(p.title)}</a>${courses.has(p.id)?` · <a href="#course/${p.id}">${courses.get(p.id).lessons.length} available lessons</a>`:' · planned'}</li>`).join('')}</ul></section>`;
}
